# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">YERYÜZÜ ŞEKİLLERİNİN BEŞERÎ VE EKONOMİK FAALİYETLERE ETKİSİ</text>\n  <rect x="20" y="42" width="210" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="125" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">OVA VE ALÇAK DÜZLÜKLER</text>\n  <text x="30" y="88" font-size="10.8" fill="#14532d">• Kalın alüvyal toprak örtüsü</text>\n  <text x="30" y="112" font-size="10.8" fill="#14532d">• Yoğun tarım ve agro-endüstri</text>\n  <text x="30" y="136" font-size="10.8" fill="#14532d">• Toplu yerleşme ve sık nüfus</text>\n  <text x="30" y="160" font-size="10.8" fill="#14532d">• Düşük yol yapım maliyeti</text>\n  <text x="30" y="184" font-size="10.8" fill="#14532d">• Örnek: Çukurova, Gediz, Bafra</text>\n  <rect x="245" y="42" width="210" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">PLATOLAR VE VADİLER</text>\n  <text x="255" y="88" font-size="10.8" fill="#1e3a8a">• Tahıl tarımı ve mera hayvancılığı</text>\n  <text x="255" y="112" font-size="10.8" fill="#1e3a8a">• Çentik vadilerde hidroelektrik (HES)</text>\n  <text x="255" y="136" font-size="10.8" fill="#1e3a8a">• Kanyon vadilerde doğa turizmi</text>\n  <text x="255" y="160" font-size="10.8" fill="#1e3a8a">• Çatalca-Kocaeli: Sanayi-ulaşım</text>\n  <text x="255" y="184" font-size="10.8" fill="#1e3a8a">• Erzurum-Kars: Büyükbaş mera</text>\n  <rect x="470" y="42" width="210" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="575" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">DAĞLIK VE ENGEBELİ ALANLAR</text>\n  <text x="480" y="88" font-size="10.8" fill="#7c2d12">• Seyrek nüfus ve dağınık yerleşme</text>\n  <text x="480" y="112" font-size="10.8" fill="#7c2d12">• Tarım alanları dar ve parçalı</text>\n  <text x="480" y="136" font-size="10.8" fill="#7c2d12">• Ulaşım geçit, tünel ve viyadükle</text>\n  <text x="480" y="160" font-size="10.8" fill="#7c2d12">• Kış turizmi, yaylacılık, ormancılık</text>\n  <text x="480" y="184" font-size="10.8" fill="#7c2d12">• Örnek: Doğu Karadeniz, Hakkâri</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Yükselti, eğim ve bakı koşulları; yerleşme dokusunu, tarım ürünlerini ve ulaşım ağlarını doğrudan şekillendirir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">YAKIN ÇEVRE SORGULAMA BASAMAKLARI VE ANTROPOJENİK ETKİLER</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">COĞ.10.3.5 SORGULAMA SÜRECİ</text>\n  <text x="35" y="88" font-size="11.2" fill="#581c87">1. Merak edilen coğrafi soruları sorma (Neden-Nasıl?)</text>\n  <text x="35" y="112" font-size="11.2" fill="#581c87">2. Harita, CBS, uydu görüntüsü ve sahadan bilgi toplama</text>\n  <text x="35" y="136" font-size="11.2" fill="#581c87">3. Toplanan verileri tablo ve grafiklerle düzenleme</text>\n  <text x="35" y="160" font-size="11.2" fill="#581c87">4. Doğal şekil ile beşerî faaliyet ilişkisini çözümleme</text>\n  <text x="35" y="184" font-size="11.2" fill="#581c87">5. Sürdürülebilir arazi kullanım sonuçlarını paylaşma</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">İNSANIN YERYÜZÜNÜ DEĞİŞTİRMESİ (ANTROPOJENİK)</text>\n  <text x="370" y="88" font-size="11.2" fill="#7f1d1d">• Ulaşım: Ovit, Zigana tünelleri; köprü ve viyadükler</text>\n  <text x="370" y="112" font-size="11.2" fill="#7f1d1d">• Kıyı dolgusu: Ordu-Giresun ve Rize-Artvin havalimanları</text>\n  <text x="370" y="136" font-size="11.2" fill="#7f1d1d">• Madencilik: Açık maden ocakları ve taş ocağı çukurları</text>\n  <text x="370" y="160" font-size="11.2" fill="#7f1d1d">• Yanlış kullanım: Birinci sınıf tarım ovalarında yapılaşma</text>\n  <text x="370" y="184" font-size="11.2" fill="#7f1d1d">• Taşkın riski: Dere yataklarının yerleşime açılması</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Teknolojik gelişmeler insanın topoğrafyaya müdahale gücünü artırsa da doğal denge gözetilmelidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">3. ÜNİTE GENEL SENTEZİ: İÇ VE DIŞ KUVVETLERDEN BEŞERÎ ETKİLEŞİME</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#065f46">YAPICI İÇ KUVVETLER (ENERJİ: MANTO)</text>\n  <text x="35" y="88" font-size="11.2" fill="#064e3b">• Orojenez: Kıvrım (Toroslar) ve Kırık dağları (Ege horst-graben)</text>\n  <text x="35" y="112" font-size="11.2" fill="#064e3b">• Epirojenez: Kara-deniz seviyesi değişimi, kıyı taraçaları</text>\n  <text x="35" y="136" font-size="11.2" fill="#064e3b">• Volkanizma: Peribacası tüfleri, mineralce zengin topraklar</text>\n  <text x="35" y="160" font-size="11.2" fill="#064e3b">• Depremler (Seizma): Fay hatları ve jeotermal sıcak su</text>\n  <text x="35" y="184" font-size="11.2" fill="#064e3b">• Kayaç döngüsü: Magmatik, tortul ve başkalaşım kayaçları</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">ŞEKİLLENDİRİCİ DIŞ KUVVETLER (ENERJİ: GÜNEŞ)</text>\n  <text x="370" y="88" font-size="11.2" fill="#713f12">• Akarsular: Vadi, menderes, birikinti konisi, delta ovası</text>\n  <text x="370" y="112" font-size="11.2" fill="#713f12">• Karstik süreçler: Lapya, dolin, polye, mağara, traverten</text>\n  <text x="370" y="136" font-size="11.2" fill="#713f12">• Rüzgârlar: Mantarkaya, şahitkaya, barkan, lös (kurak bölge)</text>\n  <text x="370" y="160" font-size="11.2" fill="#713f12">• Buzullar: Sirk gölü, hörgüçkaya, buzul vadisi, moren</text>\n  <text x="370" y="184" font-size="11.2" fill="#713f12">• Dalga ve akıntılar: Falez, kıyı oku, lagün, tombolo</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">İç kuvvetlerin oluşturduğu ana çatıyı dış kuvvetler işler; insan ise bu mekân üzerinde yaşamını kurar.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
